import json
from datetime import timezone
from pathlib import Path

from mock_api import TRACE, search
from query_audit import build_rejection
from timezone_defaults import DEFAULT_TIMEZONE, MISSING_TZ_POLICY
from window_projection import parse_bound


UTC = timezone.utc


def _normalized_bound(value):
    """Parse a bound and return it together with the normalization metadata."""
    parsed = parse_bound(value)
    return parsed, {
        "input": value,
        "timezone": str(parsed.tzinfo),
        "defaulted_to_utc": parsed.tzinfo == DEFAULT_TIMEZONE and _is_naive(value),
        "utc": parsed.astimezone(UTC).isoformat(),
    }


def _is_naive(value):
    # Parsing first is deliberately left to datetime.fromisoformat in
    # parse_bound; this helper only determines whether the original ISO value
    # supplied an offset.
    return not (value.endswith("Z") or "+" in value[10:] or "-" in value[10:])


def _error(param, message, payload, normalized=None):
    return build_rejection(param, message, payload, normalized)


def validate_range(payload):
    if not isinstance(payload, dict):
        return [_error("query", "query must be an object", payload)]

    errors = []
    bounds = {}
    metadata = {}

    for param in ("start_date", "end_date"):
        if param == "end_date" and param not in payload:
            continue
        if param not in payload:
            errors.append(_error(param, "required", payload))
            continue
        value = payload[param]
        if not isinstance(value, str):
            errors.append(_error(param, "must be an ISO 8601 string", payload))
            continue
        try:
            bounds[param], metadata[param] = _normalized_bound(value)
        except (TypeError, ValueError) as exc:
            errors.append(_error(param, f"invalid ISO 8601 datetime: {exc}", payload))

    if "start_date" not in bounds or "end_date" not in bounds:
        return errors

    start = bounds["start_date"]
    end = bounds["end_date"]
    normalized = {
        "start_utc": start.astimezone(UTC).isoformat(),
        "end_utc": end.astimezone(UTC).isoformat(),
        "default_timezone": str(DEFAULT_TIMEZONE),
        "start": metadata["start_date"],
        "end": metadata["end_date"],
    }

    # Equality is a valid zero-length range. Only a strictly earlier UTC end
    # is invalid under the API contract.
    if end.astimezone(UTC) < start.astimezone(UTC):
        errors.append(_error(
            "date_range",
            f"end must not be before start after UTC normalization ({MISSING_TZ_POLICY})",
            payload,
            normalized,
        ))

    # During the repeated fall-back hour, mixed offsets plus a backwards local
    # clock movement is treated as ambiguous input by the service. This check
    # intentionally supplements (rather than replaces) the UTC comparison.
    start_local = start.replace(tzinfo=None)
    end_local = end.replace(tzinfo=None)
    if (
        start.date() == end.date()
        and start.hour == end.hour
        and start.utcoffset() != end.utcoffset()
        and end_local < start_local
    ):
        errors.append(_error(
            "date_range",
            "ambiguous fall-back DST range: local end clock is earlier than local start clock",
            payload,
            normalized,
        ))

    return errors


def process_queries(path):
    TRACE.clear()
    payload = json.loads(Path(path).read_text(encoding="utf-8"))
    accepted = []
    rejected = []
    for index, query in enumerate(payload):
        errors = validate_range(query)
        if errors:
            rejected.append({"index": index, "errors": errors, "original": query})
            continue
        accepted.append(search(query))
    return {"accepted": accepted, "rejected": rejected, "trace": list(TRACE)}

